		"context",
		"codebase",
		"analyzer",
		"claude",
		"opencode",
		"token-saver",
		"project-scanner"
	],
	"author": "Jul879n",
	"license": "MIT",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/Jul879n/reposynapse.git"
	},
	"bugs": {
		"url": "https://github.com/Jul879n/reposynapse/issues"
	},
	"homepage": "https://github.com/Jul879n/reposynapse#readme",
	"engines": {
		"node": ">=18.0.0"
	},
	"files": [
		"dist",
		"bin",
		"README.md",
		"LICENSE"
	],
	"dependencies": {
		"@modelcontextprotocol/sdk": "^1.12.0",
